import socket, struct
def dnsq(name, qtype):
    hdr=b'\x12\x34\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00'
    qn=b''.join(bytes([len(p)])+p.encode() for p in name.split('.'))+b'\x00'
    pkt=hdr+qn+struct.pack("!HH",qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(3)
    try:
        s.sendto(pkt,("127.0.0.11",53))
        d,_=s.recvfrom(4096)
        rcode=d[3]&0xF; an=struct.unpack("!H",d[6:8])[0]
        return rcode,an,d
    except Exception as e:
        return None,None,str(e)
    finally: s.close()
def show(name,qtype,label):
    rc,an,d = dnsq(name,qtype)
    print(f"[{label}] {name}: rcode={rc} answers={an}")
    if an:
        print("   ", d.hex())
types={1:'A',16:'TXT',5:'CNAME',33:'SRV',12:'PTR',2:'NS',6:'SOA'}
